('cmvrc77zw000fjm12wa7wqwfw', 'রবীন্দ্রনাথ ঠাকুর', 'Rabindranath Tagore', 'rabindranath-tagore', 'নোবেল বিজয়ী বিশ্বকবি, বাঙালি সাহিত্যের প্রাণপুরুষ।', NULL, 'https://images.unsplash.com/photo-1544717305-2782549b5136?w=400', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ACTIVE', TRUE, TRUE, TRUE, NULL, NULL, NULL, NULL, '2026-10-27T23:49:01.629Z', '2026-10-27T23:49:01.629Z'),
('cmvrc787t000gjm12i9vcsuaz', 'কাজী নজরুল ইসলাম', 'Kazi Nazrul Islam', 'kazi-nazrul-islam', 'বাংলাদেশের জাতীয় কবি, বিদ্রোহী কবি ও মানবতার উদাত্ত কণ্ঠস্বর।', NULL, 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=400', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ACTIVE', TRUE, TRUE, TRUE, NULL, NULL, NULL, NULL, '2026-10-27T23:49:01.914Z', '2026-10-27T23:49:01.914Z'),
('cmvrc78fq000hjm12aurkct8s', 'ড. মুহম্মদ শহীদুল্লাহ', 'Dr. Muhammad Shahidullah', 'muhammad-shahidullah', 'প্রখ্যাত বহুভাষাবিদ, শিক্ষাবিদ ও বাংলা সাহিত্যের অন্যতম শ্রেষ্ঠ গবেষক।', NULL, 'https://images.unsplash.com/photo-1570295999919-56ceb5ecca61?w=400', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ACTIVE', TRUE, TRUE, TRUE, NULL, NULL, NULL, NULL, '2026-10-27T23:49:02.199Z', '2026-10-27T23:49:02.199Z'),
('cmvrc78nn000ijm12nxp0ag19', 'জসীমউদ্দীন', 'Jasimuddin', 'jasimuddin', 'পল্লীকবি হিসেবে খ্যাত, আবহমান বাংলার লোকজীবন ও প্রকৃতির রূপকার।', NULL, 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=400', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ACTIVE', TRUE, FALSE, TRUE, NULL, NULL, NULL, NULL, '2026-10-27T23:49:02.484Z', '2026-10-27T23:49:02.484Z'),
('cmvrc78vk000jjm12hn447hkf', 'মীর মশাররফ হোসেন', 'Mir Mosharraf Hossain', 'mir-mosharraf-hossain', 'বাংলা সাহিত্যের অগ্রণী মুসলিম ঔপন্যাসিক, প্রাবন্ধিক ও নাট্যকার।', NULL, 'https://images.unsplash.com/photo-1522075469751-3a6694fb2f61?w=400', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ACTIVE', TRUE, FALSE, TRUE, NULL, NULL, NULL, NULL, '2026-10-27T23:49:02.769Z', '2026-10-27T23:49:02.769Z'),
