INSERT INTO "Article" ("id", "title", "subtitle", "slug", "content", "excerpt", "coverImage", "type", "status", "authorId", "categoryId", "issueId", "magazineId", "editorialStatus", "reviewedBy", "reviewNotes", "version", "footnotes", "isFree", "price", "readingTime", "views", "isFeatured", "tags", "arabicContent", "references", "relatedBookIds", "relatedArticleIds", "metaTitle", "metaDescription", "canonicalUrl", "scheduledAt", "approvedBy", "approvedAt", "publishedAt", "createdAt", "updatedAt") VALUES
('cmvrc7du3001njm125i023lj8', 'আধুনিক বাংলা সাহিত্যে মননশীলতার ধারা ও বর্তমান সংকট', NULL, 'intellectual-tradition-in-modern-bengali-literature', 'বাংলা সাহিত্যের হাজার বছরের যাত্রায় মননশীল প্রবন্ধ ও সাহিত্যতাত্ত্বিক আলোচনা এক অনন্য স্তম্ভ। চর্যাকারদের সান্ধ্যভাষার রূপকাশ্রয়ী গভীরতা থেকে শুরু করে রামমোহন, বিদ্যাসাগর, অক্ষয়কুমার দত্ত এবং বঙ্কিমচন্দ্রের যুক্তিবাদী গদ্য আমাদের জাতিকে চিন্তা করতে শিখিয়েছে।
INSERT INTO "ResearchPaper" ("id", "title", "slug", "abstract", "content", "pdfUrl", "doi", "institution", "field", "authorId", "citationText", "downloads", "isFeatured", "publishedDate", "createdAt", "updatedAt") VALUES
('cmvrc7emq001tjm124x7tnd41', 'চর্যাপদের ধ্বনিতাত্ত্বিক বিবর্তন ও আধুনিক বাংলা ভাষার সংযোগসূত্র', 'charyapada-phonological-evolution', 'এই গবেষণাপত্রটি হরপ্রসাদ শাস্ত্রী কর্তৃক নেপাল থেকে আবিষ্কৃত প্রাচীন বাংলা চর্যাপদের ছন্দ, ধ্বনিতাত্ত্বিক বৈশিষ্ট্য এবং আধুনিক বাংলা উপভাষার সাথে এর ধ্বনিগত রূপান্তর বৈজ্ঞানিক পদ্ধতিতে বিশ্লেষণ করেছে। গবেষণায় দেখানো হয়েছে কীভাবে মাগধী অপভ্রংশ থেকে আদি বাংলার স্বর ও ব্যঞ্জনধ্বনি আধুনিক রূপ লাভ করেছে।', 'গবেষণার সম্পূর্ণ খসড়া ও ডেটাসেট সহ মূল প্রবন্ধ।', '/samples/research-charyapada.pdf', '10.5281/zenodo.shubban.2026.01', 'ঢাকা বিশ্ববিদ্যালয় ও শুব্বান গবেষণা পরিষদ', 'বাংলা ভাষাতত্ত্ব ও প্রাচীন পাণ্ডুলিপি বিদ্যা', 'cmvrc78fq000hjm12aurkct8s', 'Shahidullah, M. (2026). Phonological Evolution of Charyapada. Shubban Research Journal, 4(2), 45-78.', 148, TRUE, '2026-10-27T23:49:10.226Z', '2026-10-27T23:49:10.226Z', '2026-10-27T23:49:10.226Z')
INSERT INTO "Presentation" ("id", "title", "slug", "description", "presenter", "institution", "fileUrl", "fileType", "slidesCount", "isFeatured", "eventDate", "createdAt", "updatedAt") VALUES
('cmvrc7eun001ujm12dffe45un', 'ডিজিটাল যুগে দুর্লভ বাংলা পাণ্ডুলিপি ও বই ডিজিটাইজেশন কৌশল', 'bangla-digital-preservation-slides', 'আন্তর্জাতিক কনফারেন্সে উপস্থাপিত স্লাইড ডেক। প্রাচীন পাণ্ডুলিপির হাই-রেজোলিউশন স্ক্যানিং, অপটিক্যাল ক্যারেক্টার রিকগনিশন (OCR) এবং মেটাডাটা প্রমিতকরণ সম্পর্কিত প্রামাণ্য প্রেজেন্টেশন।', 'ড. মুহম্মদ এহসানুল কবির', 'শুব্বান তথ্য ও ডিজিটাল লাইব্রেরী সেল', '/samples/slides-manuscript-digitization.pdf', 'PDF', 36, TRUE, '2026-10-27T23:49:10.511Z', '2026-10-27T23:49:10.511Z', '2026-10-27T23:49:10.511Z')
