INSERT INTO "DonationCampaign" ("id", "title", "titleEn", "slug", "category", "description", "story", "coverImage", "goalAmount", "raisedAmount", "donorCount", "status", "startDate", "endDate", "isFeatured", "createdAt", "updatedAt") VALUES
('cmvtld0yb000812pr7f6hejzh', 'বন্যাদুর্গতদের জরুরি খাদ্য সহায়তা ও স্থায়ী পুনর্বাসন তহবিল', 'Emergency Flood Relief and Rehabilitation Fund', 'flood-relief-and-rehabilitation', 'RELIEF', 'বন্যা উপদ্রুত অঞ্চলের ক্ষতিগ্রস্ত পরিবারগুলোর জন্য শুকনো খাবার, বিশুদ্ধ পানি, চিকিৎসা সহায়তা এবং ক্ষতিগ্রস্ত ঘরবাড়ি পুনর্নির্মাণ প্রকল্প।', 'বন্যার পানিতে ভেসে গেছে হাজারো মানুষের সাজানো সংসার। শিশু ও বৃদ্ধরা অনাহারে দিনাতিপাত করছে। শুব্বান চ্যারিটি উইং সরাসরি দুর্গম এলাকায় নৌকা ও ট্রলারযোগে ত্রাণ সামগ্রী পৌঁছে দিচ্ছে। আপনার ১০০ টাকার সদকাহ হতে পারে একজন অনাহারী শিশুর দিনের খাবার।', 'https://images.unsplash.com/photo-1547683905-f686c993aae5?w=800', 5000000, 2864000, 1426, 'ACTIVE', '2026-10-29T13:41:01.332Z', NULL, TRUE, '2026-10-29T13:41:01.332Z', '2026-10-30T01:23:24.660Z'),
('cmvtld16t000912prnieyatuo', 'চর ও পাহাড়ি অঞ্চলের শিক্ষার্থীদের মাঝে বিনামূল্যে কুরআন বিতরণ', 'Free Quran Distribution for Rural Students', 'free-quran-distribution-project', 'QURAN_DISTRIBUTION', 'অর্থের অভাবে যে সকল এতিম ও দরিদ্র শিক্ষার্থী কুরআন শরীফ সংগ্রহ করতে পারে না, তাদের হাতে প্রামাণ্য বাংলা অর্থসহ কুরআন পৌঁছে দেওয়া।', 'জ্ঞান ও হিদায়াতের আলো ছড়িয়ে দিতে শুব্বান লাইব্রেরী প্রতি বছর প্রত্যন্ত অঞ্চলের মাদ্রাসা ও স্কুলে বিনামূল্যে বিশুদ্ধ ছাপা ও অনুবাদের পবিত্র কুরআন উপহার দিয়ে থাকে। প্রতি কপি কুরআনের সার্বিক ব্যয় মাত্র ৩০০ টাকা।', 'https://images.unsplash.com/photo-1609599006353-e629aaabfeae?w=800', 1000000, 720000, 850, 'ACTIVE', '2026-10-29T13:41:01.637Z', NULL, TRUE, '2026-10-29T13:41:01.637Z', '2026-10-29T13:41:01.637Z'),
('cmvtld1eq000a12prkg0w40vq', 'উপকূলীয় অঞ্চলে সুপেয় পানির গভীর নলকূপ ও ওয়াটার প্ল্যান্ট স্থাপন', 'Deep Tube-well & Clean Drinking Water Project', 'safe-drinking-water-plant', 'WATER_WELL', 'লবণাক্ত ও আর্সেনিকযুক্ত এলাকায় অসহায় মানুষের জন্য দীর্ঘমেয়াদী সদকায়ে জারিয়া হিসেবে সুপেয় খাবার পানির ব্যবস্থা।', 'সাদাকাহর মধ্যে শ্রেষ্ঠ হলো পানির ব্যবস্থা করা (হাদিস)। উপকূলীয় খুলনা, সাতক্ষীরা ও বাগেরহাটের প্রত্যন্ত গ্রামে প্রতিদিন মাইলের পর মাইল হেঁটে খাবার পানি আনতে হয় মা-বোনদের। একটি গভীর নলকূপ শত শত মানুষের তৃষ্ণা নিবারণ করতে পারে।', 'https://images.unsplash.com/photo-1541888946425-d0fbb186c5f7?w=800', 2500000, 1800000, 630, 'ACTIVE', '2026-10-29T13:41:01.922Z', NULL, TRUE, '2026-10-29T13:41:01.922Z', '2026-10-29T13:41:01.922Z'),
('cmvuyg3870007n26qpc3qx0uf', 'উত্তরবঙ্গে শীতবস্ত্র বিতরণ ও খাদ্য সহায়তা - 1793363705430', NULL, 'winter-aid-1793363705430', 'WINTER_AID', 'কুড়িগ্রাম ও পঞ্চগড়ের শীতার্ত অসহায় পরিবারের মাঝে উন্নত মানের কম্বল বিতরণ।', 'তীব্র শীতে অসহায় শিশুদের উষ্ণতা পৌঁছে দিতে আমাদের সাথে অংশ নিন।', '/images/hero-1.jpg', 100000, 5000, 1, 'ACTIVE', '2026-10-30T12:35:05.432Z', NULL, TRUE, '2026-10-30T12:35:05.432Z', '2026-10-30T12:35:06.906Z'),
