INSERT INTO "SupportTicket" ("id", "ticketNumber", "userId", "subject", "category", "priority", "status", "message", "orderId", "createdAt", "updatedAt") VALUES
('cmvuc0jd60001iqthj2yo0ely', 'TKT-2026-001', 'cmvrc74un0001jm12tes4ll7p', 'অর্ডারের ডেলিভারি ট্র্যাকিং ও সম্ভাব্য ডেলিভারি তারিখ', 'ORDER', 'HIGH', 'OPEN', 'আমার অর্ডারটির বর্তমান অবস্থান জানতে চাচ্ছি। গতকাল এসএমএস পেয়েছিলাম কিন্তু ট্র্যাকিং লিংকে এখনও আপডেট দেখতে পাচ্ছি না। বইটি কবে নাগাদ হাতে পাব?', 'SHB-2026-94359', '2026-10-30T02:07:08.298Z', '2026-10-30T02:07:08.298Z'),
('cmvuc0jn90005iqthacvl6jr4', 'TKT-2026-002', 'cmvrc74un0001jm12tes4ll7p', 'বইয়ের পৃষ্ঠা বাঁধাই ত্রুটি ও প্রতিস্থাপন সংক্রান্ত জিজ্ঞাসা', 'RETURN', 'MEDIUM', 'IN_PROGRESS', 'গত সপ্তাহে পাওয়া একটি বইয়ের ১৬ থেকে ৩২ নম্বর পৃষ্ঠা অসম্পূর্ণ প্রিন্ট হয়েছে। বইটি কি এক্সচেঞ্জ করে নতুন কপি নেওয়া যাবে?', NULL, '2026-10-30T02:07:08.662Z', '2026-10-30T02:07:08.662Z'),
('cmvuc0jxz0009iqthpsjqb7qn', 'TKT-2026-003', 'cmvrc74un0001jm12tes4ll7p', 'বিকাশ পেমেন্ট ট্রানজেকশন ভেরিফিকেশন', 'PAYMENT', 'LOW', 'RESOLVED', 'বিকাশে পেমেন্ট করার পর ট্রানজেকশন আইডি ইনপুট দিতে বিলম্ব হয়েছিল। অনুগ্রহ করে অর্ডারটি কনফার্ম হয়েছে কিনা জানাবেন।', NULL, '2026-10-30T02:07:09.048Z', '2026-10-30T02:07:09.048Z')
INSERT INTO "TicketResponse" ("id", "ticketId", "userId", "message", "isAdmin", "createdAt") VALUES
('cmvuc0jd60003iqth365dwi8n', 'cmvuc0jd60001iqthj2yo0ely', 'cmvrc74un0001jm12tes4ll7p', 'আমি ঢাকা উত্তর থেকে অর্ডার করেছি। দয়া করে একটু দ্রুত ডেলিভারির ব্যবস্থা করবেন।', FALSE, '2026-10-30T02:07:08.298Z'),
('cmvuc0jna0007iqthod9w9rg2', 'cmvuc0jn90005iqthacvl6jr4', 'cmvrc74un0001jm12tes4ll7p', 'ত্রুটিযুক্ত পৃষ্ঠার ছবি আমি মেইলে পাঠাতে পারব।', FALSE, '2026-10-30T02:07:08.662Z'),
