INSERT INTO "QuranVerse" ("id", "surahNumber", "surahNameAr", "surahNameEn", "surahNameBn", "ayahNumber", "textAr", "textNormalized", "juzNumber", "revelationType") VALUES
('cmvw49omx0000gqdoeq6gf11j', 1, 'الفاتحة', 'Al-Fatihah', 'সূরা আল-ফাতিহা', 1, 'بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ', 'بسم الله الرحمن الرحيم', 1, 'MECCAN'),
('cmvw49pov0007gqdo8vlahnjp', 1, 'الفاتحة', 'Al-Fatihah', 'সূরা আল-ফাতিহা', 2, 'الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ', 'الحمد لله رب العالمين', 1, 'MECCAN'),
('cmvw49qu0000egqdom5oq6wpk', 2, 'البقرة', 'Al-Baqarah', 'সূরা আল-বাক্বারাহ', 43, 'وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ', 'واقيموا الصلاه واتوا الزكاه واركعوا مع الراكعين', 1, 'MEDINAN'),
('cmvw49rqa000lgqdoq7zirkx1', 2, 'البقرة', 'Al-Baqarah', 'সূরা আল-বাক্বারাহ', 183, 'يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ', 'يا ايها الذين امنوا كتب عليكم الصيام كما كتب علي الذين من قبلكم لعلكم تتقون', 2, 'MEDINAN'),
('cmvw49sm0000sgqdo2qq7ifv8', 2, 'البقرة', 'Al-Baqarah', 'সূরা আল-বাক্বারাহ', 255, 'اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَن ذَا الَّذِي يَشْفَعُ عِندَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ', 'الله لا اله الا هو الحي القيوم  لا تاخذه سنه ولا نوم  له ما في السماوات وما في الارض  من ذا الذي يشفع عنده الا باذنه  يعلم ما بين ايديهم وما خلفهم  ولا يحيطون بشيء من علمه الا بما شاء  وسع كرسيه السماوات والارض  ولا يئوده حفظهما  وهو العلي العظيم', 3, 'MEDINAN'),
('cmvw49thl000zgqdoiafvkayc', 112, 'الإخلاص', 'Al-Ikhlas', 'সূরা আল-ইখলাস', 1, 'قُلْ هُوَ اللَّهُ أَحَدٌ', 'قل هو الله احد', 30, 'MECCAN')
INSERT INTO "QuranTranslation" ("id", "verseId", "language", "translator", "translation", "sourceName") VALUES
('cmvw49ox60002gqdomqvwa8pi', 'cmvw49omx0000gqdoeq6gf11j', 'bn', 'মুহিউদ্দীন খান', 'পরম করুণাময় অসীম দয়ালু আল্লাহর নামে (শুরু করছি)।', 'মদীনা মুনাওয়ারা বাদশাহ ফাহদ কুরআন কমপ্লেক্স'),
('cmvw49p6l0004gqdo231gwcyf', 'cmvw49omx0000gqdoeq6gf11j', 'en', 'Sahih International', 'In the name of Allah, the Entirely Merciful, the Especially Merciful.', 'Al-Muntada Al-Islami'),
('cmvw49pwu0009gqdocws8ol44', 'cmvw49pov0007gqdo8vlahnjp', 'bn', 'মুহিউদ্দীন খান', 'যাবতীয় প্রশংসা জগৎসমূহের প্রতিপালক আল্লাহরই জন্য।', 'মদীনা মুনাওয়ারা বাদশাহ ফাহদ কুরআন কমপ্লেক্স'),
('cmvw49q4p000bgqdoy7o4cw0e', 'cmvw49pov0007gqdo8vlahnjp', 'en', 'Sahih International', '[All] praise is [due] to Allah, Lord of the worlds.', 'Al-Muntada Al-Islami'),
('cmvw49r27000ggqdo0mw990b9', 'cmvw49qu0000egqdom5oq6wpk', 'bn', 'মুহিউদ্দীন খান', 'আর তোমরা নামাজ কায়েম করো, যাকাত প্রদান করো এবং রুকুকারীদের সাথে রুকু করো।', 'মদীনা মুনাওয়ারা বাদশাহ ফাহদ কুরআন কমপ্লেক্স'),
('cmvw49ra3000igqdok6m0hv4r', 'cmvw49qu0000egqdom5oq6wpk', 'en', 'Sahih International', 'And establish prayer and give zakah and bow with those who bow [in worship and obedience].', 'Al-Muntada Al-Islami'),
('cmvw49ry6000ngqdo3rv6th7v', 'cmvw49rqa000lgqdoq7zirkx1', 'bn', 'মুহিউদ্দীন খান', 'হে মুমিনগণ! তোমাদের ওপর রোজা ফরজ করা হয়েছে, যেরূপ ফরজ করা হয়েছিল তোমাদের পূর্ববর্তীদের ওপর; যেন তোমরা তাকওয়া (আল্লাহভীতি) অর্জন করতে পারো।', 'মদীনা মুনাওয়ারা বাদশাহ ফাহদ কুরআন কমপ্লেক্স'),
('cmvw49s62000pgqdorwyik22o', 'cmvw49rqa000lgqdoq7zirkx1', 'en', 'Sahih International', 'O you who have believed, decreed upon you is fasting as it was decreed upon those before you that you may become righteous.', 'Al-Muntada Al-Islami'),
('cmvw49stw000ugqdohs19s0w8', 'cmvw49sm0000sgqdo2qq7ifv8', 'bn', 'মুহিউদ্দীন খান', 'আল্লাহ, তিনি ছাড়া কোনো সত্য ইলাহ নেই; তিনি চিরঞ্জীব, সবকিছুর ধারক। তন্দ্রা বা নিদ্রা তাঁকে স্পর্শ করে না। আসমান ও যমীনে যা কিছু রয়েছে সবই তাঁর। কে আছে যে তাঁর অনুমতি ছাড়া তাঁর নিকট সুপারিশ করবে? তাদের সামনে ও পেছনে যা কিছু আছে তা তিনি জানেন। আর তাঁর জ্ঞানের কোনো কিছুকেই তারা আয়ত্ত করতে পারে না, তিনি যতটুকু ইচ্ছে করেন তা ছাড়া। তাঁর কুরসী আসমান ও যমীনকে পরিবেষ্টন করে আছে, আর এ দুটির রক্ষণাবেক্ষণ তাঁর জন্য কোনো বোঝা নয়; তিনিই সুউচ্চ, মহামহিম।', 'মদীনা মুনাওয়ারা বাদশাহ ফাহদ কুরআন কমপ্লেক্স'),
('cmvw49t1s000wgqdom7vznmqa', 'cmvw49sm0000sgqdo2qq7ifv8', 'en', 'Sahih International', 'Allah - there is no deity except Him, the Ever-Living, the Sustainer of [all] existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth...', 'Al-Muntada Al-Islami'),
('cmvw49tpi0011gqdo2qylpqb4', 'cmvw49thl000zgqdoiafvkayc', 'bn', 'মুহিউদ্দীন খান', 'বলুন, তিনিই আল্লাহ, একক ও অদ্বিতীয়।', 'মদীনা মুনাওয়ারা বাদশাহ ফাহদ কুরআন কমপ্লেক্স'),
('cmvw49txf0013gqdozuwp2ub1', 'cmvw49thl000zgqdoiafvkayc', 'en', 'Sahih International', 'Say, "He is Allah, [who is] One."', 'Al-Muntada Al-Islami')
INSERT INTO "TafsirEntry" ("id", "verseId", "sourceName", "author", "volume", "page", "content", "language") VALUES
('cmvw49pem0006gqdotiihfzu7', 'cmvw49omx0000gqdoeq6gf11j', 'তাফসীরে ইবনে কাসীর', 'আল্লামা ইমাদুদ্দীন ইবনে কাসীর (রহ.)', NULL, NULL, 'ইমাম ইবনে কাসীর (রহ.) বলেন, সকল কল্যাণকর কাজের সূচনায় বিসমিল্লাহ পাঠ করা সুন্নাত ও বরকতময়।', 'bn'),
('cmvw49qk4000dgqdo7nxvqho5', 'cmvw49pov0007gqdo8vlahnjp', 'তাফসীরে ইবনে কাসীর', 'আল্লামা ইমাদুদ্দীন ইবনে কাসীর (রহ.)', NULL, NULL, 'আল-হামদু দ্বারা আল্লাহর প্রতি পূর্ণ ভালোবাসা ও মর্যাদার সাথে সর্বাত্মক কৃতজ্ঞতা প্রকাশ বোঝায়।', 'bn'),
('cmvw49ri3000kgqdorptkhipb', 'cmvw49qu0000egqdom5oq6wpk', 'তাফসীরে ইবনে কাসীর', 'আল্লামা ইমাদুদ্দীন ইবনে কাসীর (রহ.)', NULL, NULL, 'মুফতী শফী (রহ.) মাআরিফুল কুরআনে লিখেছেন, এই আয়াতে জামাআতে সালাত আদায়ের গুরুত্ব এবং ইসলামের অন্যতম স্তম্ভ যাকাত প্রদানের সুস্পষ্ট নির্দেশ রয়েছে।', 'bn'),
('cmvw49se1000rgqdof4phdlk4', 'cmvw49rqa000lgqdoq7zirkx1', 'তাফসীরে ইবনে কাসীর', 'আল্লামা ইমাদুদ্দীন ইবনে কাসীর (রহ.)', NULL, NULL, 'তাফসীরে ইবনে কাসীর: রোজার মূল উদ্দেশ্য কেবল পানাহার বর্জন নয়, বরং তাকওয়া তথা আত্মশুদ্ধি ও আত্মসংযম অর্জন।', 'bn'),
('cmvw49t9o000ygqdow2eq76qf', 'cmvw49sm0000sgqdo2qq7ifv8', 'তাফসীরে ইবনে কাসীর', 'আল্লামা ইমাদুদ্দীন ইবনে কাসীর (রহ.)', NULL, NULL, 'এটি কুরআনের সর্বশ্রেষ্ঠ আয়াত (আয়াতুল কুরসী)। উবাই ইবনে কাআব (রা.) বর্ণিত সহিহ হাদিসে নবীজী (সা.) একে কুরআনের সবচেয়ে মর্যাদাপূর্ণ আয়াত হিসেবে নিশ্চিত করেছেন।', 'bn'),
('cmvw49u5c0015gqdoxsgj4trx', 'cmvw49thl000zgqdoiafvkayc', 'তাফসীরে ইবনে কাসীর', 'আল্লামা ইমাদুদ্দীন ইবনে কাসীর (রহ.)', NULL, NULL, 'তাওহীদের মূল ভিত্তি এই সূরায় সংক্ষেপে অথচ নিখুঁতভাবে বিধৃত হয়েছে। বুখারীর বর্ণনায় এই সূরা কুরআনের এক-তৃতীয়াংশের সমতুল্য।', 'bn')
INSERT INTO "HadithCollection" ("id", "slug", "nameAr", "nameEn", "nameBn", "compiler", "totalHadith", "isCanonical") VALUES
('cmvw49ufj0016gqdo391vlht8', 'bukhari', 'صحيح البخاري', 'Sahih al-Bukhari', 'সহীহুল বুখারী', 'ইমাম মুহাম্মদ বিন ইসমাঈল আল-বুখারী (রহ.) [১৯৪-২৫৬ হি.]', 7563, TRUE),
('cmvw49urz0017gqdoha50cshg', 'muslim', 'صحيح مسلم', 'Sahih Muslim', 'সহীহ মুসলিম', 'ইমাম মুসলিম বিন আল-হাজ্জাজ (রহ.) [২০৬-২৬১ হি.]', 7500, TRUE),
('cmvw49uzx0018gqdo1iddfqyr', 'abu-dawud', 'سنن أبي داود', 'Sunan Abu Dawud', 'সুনানে আবু দাউদ', 'ইমাম আবু দাউদ সুলাইমান বিন আশআস (রহ.) [২০২-২৭৫ হি.]', 5274, TRUE),
('cmvw49v830019gqdo35adbht7', 'tirmidhi', 'جامع الترمذي', 'Jami'' at-Tirmidhi', 'জামে আত-তিরমিযী', 'ইমাম আবু ঈসা মুহাম্মদ বিন ঈসা আত-তিরমিযী (রহ.) [২০৯-২৭৯ হি.]', 3956, TRUE)
INSERT INTO "HadithEntry" ("id", "collectionId", "hadithNumber", "chapterNameBn", "chapterNameAr", "chapterNameEn", "narrator", "textAr", "textBn", "textEn", "authenticity", "gradingAuthority", "topicTag", "sourceUrl") VALUES
('cmvw49vge001bgqdo1tllsequ', 'cmvw49ufj0016gqdo391vlht8', 1, 'ওহীর সূচনা অধ্যায়', 'كتاب بدء الوحي', NULL, 'আমীরুল মুমিনীন হযরত উমর ইবনুল খাত্তাব (রা.)', 'إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى دُنْيَا يُصِيبُهَا أَوْ إِلَى امْرَأَةٍ يَنْكِحُهَا فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ', 'নিশ্চয়ই যাবতীয় কাজের ফলাফল নিয়তের ওপর নির্ভরশীল। প্রত্যেক মানুষ তাই পাবে যার সে নিয়ত করে। অতএব যার হিজরত পার্থিব স্বার্থ অর্জনের উদ্দেশ্যে কিংবা কোনো নারীকে বিয়ে করার উদ্দেশ্যে হবে, তার হিজরত সেই উদ্দেশ্যেই গণ্য হবে।', 'The reward of deeds depends upon the intentions and every person will get the reward according to what he has intended...', 'SAHIH', 'ইমাম বুখারী ও ইমাম মুসলিম (মুত্তাফাকুন আলাইহি)', 'NIYYAH', 'https://sunnah.com/bukhari:1'),
('cmvw49vq8001dgqdor24pajnu', 'cmvw49ufj0016gqdo391vlht8', 8, 'ঈমান অধ্যায়', 'كتاب الإيمان', NULL, 'হযরত আবদুল্লাহ ইবনে উমর (রা.)', 'بُنِيَ الإِسْلاَمُ عَلَى خَمْسٍ: شَهَادَةِ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَإِقَامِ الصَّلاَةِ، وَإِيتَاءِ الزَّكَاةِ، وَالْحَجِّ، وَصَوْمِ رَمَضَانَ', 'ইসলাম পাঁচটি স্তম্ভের ওপর প্রতিষ্ঠিত: ১. এই সাক্ষ্য দেওয়া যে আল্লাহ ছাড়া কোনো সত্য ইলাহ নেই এবং মুহাম্মদ (সা.) আল্লাহর রাসূল, ২. নামাজ কায়েম করা, ৩. যাকাত আদায় করা, ৪. হজ পালন করা এবং ৫. রমজানের রোজা রাখা।', 'Islam is based on (the following) five (principles): 1. To testify that none has the right to be worshipped but Allah and Muhammad is Allah''s Messenger. 2. To offer the (compulsory congregational) prayers dutifully and perfectly. 3. To pay Zakat. 4. To perform Hajj. 5. To observe fast during the month of Ramadan.', 'SAHIH', 'ইমাম বুখারী', 'SALAH', 'https://sunnah.com/bukhari:8'),
('cmvw49w2t001fgqdoqc2mwa5y', 'cmvw49ufj0016gqdo391vlht8', 13, 'ঈমান অধ্যায়', 'كتاب الإيمان', NULL, 'হযরত আনাস (রা.)', 'لاَ يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ', 'তোমাদের কেউ প্রকৃত মুমিন হতে পারবে না, যতক্ষণ না সে তার ভাইয়ের জন্য তাই পছন্দ করবে যা সে নিজের জন্য পছন্দ করে।', 'None of you will have faith till he wishes for his (Muslim) brother what he likes for himself.', 'SAHIH', 'ইমাম বুখারী ও ইমাম মুসলিম', 'CHARACTER', 'https://sunnah.com/bukhari:13'),
('cmvw49wan001hgqdosgrxc8kh', 'cmvw49urz0017gqdoha50cshg', 2699, 'যিকির, দোয়া ও ইলম অধ্যায়', 'كتاب الذكر والدعاء والتوبة والاستغفار', NULL, 'হযরত আবু হুরায়রা (রা.)', 'مَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا سَهَّلَ اللَّهُ لَهُ بِهِ طَرِيقًا إِلَى الْجَنَّةِ', 'যে ব্যক্তি জ্ঞান অন্বেষণের উদ্দেশ্যে কোনো পথে চলে, আল্লাহ তাআলা তার জন্য জান্নাতের পথ সুগম ও সহজ করে দেন।', 'He who treads the path in search of knowledge, Allah will make the path to Jannah easy for him.', 'SAHIH', 'ইমাম মুসলিম', 'KNOWLEDGE', 'https://sunnah.com/muslim:2699'),
('cmvw49wn7001jgqdonkiiqb86', 'cmvw49ufj0016gqdo391vlht8', 1894, 'সাওম বা রোজা অধ্যায়', 'كتاب الصوم', NULL, 'হযরত আবু হুরায়রা (রা.)', 'مَنْ صَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ', 'যে ব্যক্তি ঈমানের সাথে ও সওয়াবের প্রত্যাশায় রমজানের রোজা রাখবে, তার পূর্ববর্তী সমস্ত গুনাহ ক্ষমা করে দেওয়া হবে।', 'Whoever observes fasts during the month of Ramadan out of sincere faith, and hoping to attain Allah''s rewards, then all his past sins will be forgiven.', 'SAHIH', 'ইমাম বুখারী ও ইমাম মুসলিম', 'SAWM', 'https://sunnah.com/bukhari:1894'),
('cmvw49wvl001lgqdoyanipjyo', 'cmvw49v830019gqdo35adbht7', 2516, 'কেয়ামতের বর্ণনা ও যুহদ অধ্যায়', 'كتاب صفة القيامة والرقائق والورع', NULL, 'হযরত আবদুল্লাহ ইবনে আব্বাস (রা.)', 'احْفَظِ اللَّهَ يَحْفَظْكَ، احْفَظِ اللَّهَ تَجِدْهُ تُجَاهَكَ، إِذَا سَأَلْتَ فَاسْأَلِ اللَّهَ، وَإِذَا اسْتَعَنْتَ فَاسْتَعِنْ بِاللَّهِ', 'আল্লাহর বিধানসমূহ হেফাজত করো, আল্লাহ তোমাকে রক্ষা করবেন। আল্লাহর সন্তুষ্টি রক্ষা করো, তুমি তাঁকে তোমার সামনে পাবে। যখন কোনো কিছু প্রার্থনা করবে তখন একমাত্র আল্লাহর কাছেই প্রার্থনা করো; আর যখন সাহায্য চাইবে তখন একমাত্র আল্লাহর কাছেই সাহায্য চাও।', 'Be mindful of Allah and He will protect you. Be mindful of Allah and you will find Him before you. If you ask, ask of Allah; if that you seek help, seek help of Allah.', 'HASAN_SAHIH', 'ইমাম আত-তিরমিযী ও শায়খ আলবানী', 'TAWHID', 'https://sunnah.com/tirmidhi:2516')
INSERT INTO "ScholarlyReference" ("id", "topic", "topicEn", "madhhabViewHanafi", "madhhabViewMaliki", "madhhabViewShafii", "madhhabViewHanbali", "consensusNotes", "classicalSources", "createdAt") VALUES
('cmvw49x3j001mgqdo671490e0', 'তারাবীহর সালাতের রাকাত সংখ্যা ও মাযহাবীয় পর্যালোচনা', 'Number of Rakats in Tarawih Prayer across Madhhabs', 'হানাফি মাযহাব মতে, জামাআতের সাথে ২০ রাকাত তারাবীহ আদায় করা সুন্নাতে মুয়াক্কাদা। খলিফাতুল মুসলিমীন হযরত উমর (রা.)-এর যুগে সাহাবায়ে কেরামের সর্বসম্মত আমল ছিল ২০ রাকাত।', 'মালিকি মাযহাবের প্রাচীন ও প্রসিদ্ধ মতানুসারে মদিনাবাসীদের আমলের ওপর ভিত্তি করে ৩৬ রাকাত তারাবীহ পড়ার নিয়ম প্রচলিত ছিল। তবে ২০ রাকাতও সম্পূর্ণরূপে স্বীকৃত ও সমাদৃত।', 'ইমাম শাফিঈ (রহ.)-এর মতে ২০ রাকাত তারাবীহ সর্বোত্তম এবং মক্কার বায়তুল্লাহর মুসুল্লীগণের সর্বসম্মত আমল ২০ রাকাতই ছিল।', 'ইমাম আহমদ বিন হাম্বল (রহ.)-এর চূড়ান্ত মত অনুযায়ী তারাবীহ ২০ রাকাত। তবে ক্বিয়ামুল লাইল নফল ইবাদত হওয়ায় রাকাত সংখ্যা নিয়ে কঠোরতা না করারও অভিমত রয়েছে।', 'চার মাযহাবের জমহুর ফকীহগণের ঐকমত্য হলো ২০ রাকাত তারাবীহ সালাত সুন্নাতে মুয়াক্কাদা এবং সাহাবায়ে কেরামের যুগ থেকে এ আমল অবিচ্ছিন্নভাবে চলে আসছে। তবে কেউ ৮ রাকাত বা তার বেশি পড়লেও তা নফল হিসেবে সওয়াবের অন্তর্ভুক্ত। এটি নিয়ে মুসলিম উম্মাহর মধ্যে কাদা ছোঁড়াছুঁড়ি করা অনুচিত।', 'বাদায়েউস সানায়ে (কাসানী), আল-মুগনী (ইবনে কুদামা), আল-মাজমু শারহুল মুহাযযাব (ইমাম নববী)', '2026-10-31T08:06:01.424Z'),
('cmvw49xdm001ngqdog41np4au', 'যাকাতুল ফিতর বা ফিতরা নগদ টাকায় দেওয়ার বিধান', 'Paying Zakat al-Fitr in Cash value vs. Food', 'ইমাম আবু হানিফা (রহ.) ও হাসান বসরী (রহ.)-এর মতে ফিতরা খাদ্যদ্রব্যের পরিবর্তে তার সমমূল্যের নগদ টাকায় আদায় করা সম্পূর্ণরূপে জায়েজ ও বর্তমান যুগে গরিবদের প্রয়োজনের দৃষ্টিতে অধিক উত্তম।', 'মালিকি মাযহাব মতে মূল নিয়ম হলো হাদিসে বর্ণিত খাদ্যদ্রব্য (গম, যব, খেজুর, কিসমিস) দিয়েই ফিতরা আদায় করা।', 'ইমাম শাফিঈ (রহ.)-এর মতে দেশের প্রধান খাদ্যদ্রব্য দিয়েই ফিতরা দিতে হবে, নগদ টাকায় দিলে তা জমহুরের মতে যথেষ্ট নয়।', 'ইমাম আহমদ (রহ.)-এর সাধারণ অভিমত শাফিঈ মাযহাবের মতো খাদ্যদ্রব্য দেওয়া। তবে ইবনে তাইমিয়া (রহ.) বিশেষ প্রয়োজন বা মাসলাহাতের ক্ষেত্রে নগদ টাকায় আদায়ের অবকাশ দিয়েছেন।', 'উভয় মতেরই শক্তিশালী প্রামাণ্য ভিত্তি রয়েছে। বর্তমান আধুনিক অর্থব্যবস্থায় অভাবীদের পোশাক বা প্রয়োজনীয় সামগ্রী ক্রয়ের সুবিধার্তে হানাফি মাযহাবের মত বিশ্বজুড়ে বহু সমকালীন ফতোয়া বোর্ড কর্তৃকও গৃহীত।', 'ফাতহুল কাদীর (ইবনুল হুমাম), আল-উম্ম (ইমাম শাফিঈ), ফতোয়ায়ে উসমানী', '2026-10-31T08:06:01.786Z')
