INSERT INTO "IslamicAiMessage" ("id", "conversationId", "sender", "content", "evidenceStatus", "mode", "recommendedBookIds", "createdAt") VALUES
('cmvw4ik95000ic7h5jx6qlkkh', 'cmvw4ijuw000gc7h58ree5iuk', 'USER', 'নামাজের গুরুত্ব ও কুরআন-হাদিসের দলিল কী?', 'VERIFIED', 'STANDARD', NULL, '2026-10-31T08:12:44.682Z'),
('cmvw4ilc2000kc7h5klc0n6m1', 'cmvw4ijuw000gc7h58ree5iuk', 'AI', 'সালাত (নামাজ) ইসলামের পাঁচটি প্রধান স্তম্ভের দ্বিতীয় স্তম্ভ। কুরআনুল কারীমে আল্লাহ তাআলা একাগ্রচিত্তে নামাজ কায়েম করার নির্দেশ দিয়েছেন এবং সহিহ হাদিসে নামাজকে দ্বীনের খুঁটি ও মুমিনের অন্যতম শ্রেষ্ঠ ইবাদত হিসেবে ঘোষণা করা হয়েছে।
INSERT INTO "IslamicAiCitation" ("id", "messageId", "sourceType", "referenceId", "title", "arabicText", "translation", "grading", "sourceBook", "url", "createdAt") VALUES
('cmvw4ilc3000lc7h55ji6sw48', 'cmvw4ilc2000kc7h5klc0n6m1', 'QURAN', 'Quran:2:43', 'সূরা আল-বাক্বারাহ (সূরা নং 2, আয়াত নং 43)', 'وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ', 'আর তোমরা নামাজ কায়েম করো, যাকাত প্রদান করো এবং রুকুকারীদের সাথে রুকু করো।', NULL, 'আল-কুরআনুল কারীম', NULL, '2026-10-31T08:12:46.083Z'),
('cmvw4ilc3000mc7h5g0imq1cl', 'cmvw4ilc2000kc7h5klc0n6m1', 'TAFSIR', 'Tafsir:cmvw49ri3000kgqdorptkhipb', 'তাফসীরে ইবনে কাসীর — আল্লামা ইমাদুদ্দীন ইবনে কাসীর (রহ.)', NULL, 'মুফতী শফী (রহ.) মাআরিফুল কুরআনে লিখেছেন, এই আয়াতে জামাআতে সালাত আদায়ের গুরুত্ব এবং ইসলামের অন্যতম স্তম্ভ যাকাত প্রদানের সুস্পষ্ট নির্দেশ রয়েছে।', NULL, 'তাফসীরে ইবনে কাসীর', NULL, '2026-10-31T08:12:46.083Z'),
('cmvw4ilc3000nc7h5ayok76d4', 'cmvw4ilc2000kc7h5klc0n6m1', 'HADITH', 'bukhari:8', 'সহীহুল বুখারী (হাদিস নং 8)', 'بُنِيَ الإِسْلاَمُ عَلَى خَمْسٍ: شَهَادَةِ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَإِقَامِ الصَّلاَةِ، وَإِيتَاءِ الزَّكَاةِ، وَالْحَجِّ، وَصَوْمِ رَمَضَانَ', 'ইসলাম পাঁচটি স্তম্ভের ওপর প্রতিষ্ঠিত: ১. এই সাক্ষ্য দেওয়া যে আল্লাহ ছাড়া কোনো সত্য ইলাহ নেই এবং মুহাম্মদ (সা.) আল্লাহর রাসূল, ২. নামাজ কায়েম করা, ৩. যাকাত আদায় করা, ৪. হজ পালন করা এবং ৫. রমজানের রোজা রাখা।', 'SAHIH (ইমাম বুখারী)', 'সহীহুল বুখারী', 'https://sunnah.com/bukhari:8', '2026-10-31T08:12:46.083Z'),
('cmvw55kxw007oc7h5odh0xxs9', 'cmvw55kxw007nc7h59bihjmj1', 'QURAN', 'Quran:2:43', 'সূরা আল-বাক্বারাহ (সূরা নং 2, আয়াত নং 43)', 'وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ', 'আর তোমরা নামাজ কায়েম করো, যাকাত প্রদান করো এবং রুকুকারীদের সাথে রুকু করো।', NULL, 'আল-কুরআনুল কারীম', NULL, '2026-10-31T08:30:38.660Z'),
('cmvw55kxw007pc7h5m12uugww', 'cmvw55kxw007nc7h59bihjmj1', 'TAFSIR', 'Tafsir:cmvw49ri3000kgqdorptkhipb', 'তাফসীরে ইবনে কাসীর — আল্লামা ইমাদুদ্দীন ইবনে কাসীর (রহ.)', NULL, 'মুফতী শফী (রহ.) মাআরিফুল কুরআনে লিখেছেন, এই আয়াতে জামাআতে সালাত আদায়ের গুরুত্ব এবং ইসলামের অন্যতম স্তম্ভ যাকাত প্রদানের সুস্পষ্ট নির্দেশ রয়েছে।', NULL, 'তাফসীরে ইবনে কাসীর', NULL, '2026-10-31T08:30:38.660Z'),
('cmvw55kxw007qc7h5qiydtis1', 'cmvw55kxw007nc7h59bihjmj1', 'HADITH', 'bukhari:8', 'সহীহুল বুখারী (হাদিস নং 8)', 'بُنِيَ الإِسْلاَمُ عَلَى خَمْسٍ: شَهَادَةِ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَإِقَامِ الصَّلاَةِ، وَإِيتَاءِ الزَّكَاةِ، وَالْحَجِّ، وَصَوْمِ رَمَضَانَ', 'ইসলাম পাঁচটি স্তম্ভের ওপর প্রতিষ্ঠিত: ১. এই সাক্ষ্য দেওয়া যে আল্লাহ ছাড়া কোনো সত্য ইলাহ নেই এবং মুহাম্মদ (সা.) আল্লাহর রাসূল, ২. নামাজ কায়েম করা, ৩. যাকাত আদায় করা, ৪. হজ পালন করা এবং ৫. রমজানের রোজা রাখা।', 'SAHIH (ইমাম বুখারী)', 'সহীহুল বুখারী', 'https://sunnah.com/bukhari:8', '2026-10-31T08:30:38.660Z'),
('cmvw55m3a007wc7h5zflgp541', 'cmvw55m3a007vc7h5eu0z9igv', 'QURAN', 'Quran:2:183', 'সূরা আল-বাক্বারাহ (সূরা নং 2, আয়াত নং 183)', 'يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ', 'হে মুমিনগণ! তোমাদের ওপর রোজা ফরজ করা হয়েছে, যেরূপ ফরজ করা হয়েছিল তোমাদের পূর্ববর্তীদের ওপর; যেন তোমরা তাকওয়া (আল্লাহভীতি) অর্জন করতে পারো।', NULL, 'আল-কুরআনুল কারীম', NULL, '2026-10-31T08:30:40.150Z'),
('cmvw55m3a007xc7h5ien0uchx', 'cmvw55m3a007vc7h5eu0z9igv', 'TAFSIR', 'Tafsir:cmvw49se1000rgqdof4phdlk4', 'তাফসীরে ইবনে কাসীর — আল্লামা ইমাদুদ্দীন ইবনে কাসীর (রহ.)', NULL, 'তাফসীরে ইবনে কাসীর: রোজার মূল উদ্দেশ্য কেবল পানাহার বর্জন নয়, বরং তাকওয়া তথা আত্মশুদ্ধি ও আত্মসংযম অর্জন।', NULL, 'তাফসীরে ইবনে কাসীর', NULL, '2026-10-31T08:30:40.150Z'),
('cmvw55m3a007yc7h5v8o4i0ol', 'cmvw55m3a007vc7h5eu0z9igv', 'HADITH', 'bukhari:1894', 'সহীহুল বুখারী (হাদিস নং 1894)', 'مَنْ صَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ', 'যে ব্যক্তি ঈমানের সাথে ও সওয়াবের প্রত্যাশায় রমজানের রোজা রাখবে, তার পূর্ববর্তী সমস্ত গুনাহ ক্ষমা করে দেওয়া হবে।', 'SAHIH (ইমাম বুখারী ও ইমাম মুসলিম)', 'সহীহুল বুখারী', 'https://sunnah.com/bukhari:1894', '2026-10-31T08:30:40.150Z'),
